INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('hero.sub', '{"en":"The XXXVIII Annual Meeting of the European Eye Bank Association, hosted with KU Leuven and University Hospital Leuven. Three days, four months before the EU SoHO Regulation becomes binding.","it":"Il XXXVIII Congresso Annuale della European Eye Bank Association, ospitato con KU Leuven e l''Ospedale Universitario di Lovanio. Tre giorni, quattro mesi prima che il Regolamento europeo SoHO diventi vincolante.","nl":"De XXXVIIIe Jaarvergadering van de European Eye Bank Association, georganiseerd met KU Leuven en UZ Leuven. Drie dagen, vier maanden voordat de Europese SoHO-verordening bindend wordt.","fr":"Le XXXVIIIe Congrès annuel de l''European Eye Bank Association, accueilli avec la KU Leuven et l''Hôpital universitaire de Louvain. Trois jours, quatre mois avant que le règlement européen SoHO ne devienne contraignant."}');
