INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('ticker.items', '{"en":"XXXVIII EEBA Annual Meeting|University Hall · Leuven|Symposia · Workshops · Wetlabs|EU SoHO Regulation readiness|Abstract deadline 15 Dec 2026|Early bird until 15 Jan 2027|In collaboration with KU Leuven","it":"XXXVIII Congresso EEBA|University Hall · Lovanio|Simposi · Workshop · Wetlab|Pronti per il Regolamento SoHO|Abstract entro il 15 dic 2026|Early bird fino al 15 gen 2027|In collaborazione con KU Leuven","nl":"XXXVIIIe EEBA Jaarvergadering|Universiteitshal · Leuven|Symposia · Workshops · Wetlabs|Klaar voor de SoHO-verordening|Abstracts tot 15 dec 2026|Early bird tot 15 jan 2027|In samenwerking met KU Leuven","fr":"XXXVIIIe Congrès EEBA|Halle universitaire · Louvain|Symposiums · Ateliers · Wetlabs|Prêts pour le règlement SoHO|Résumés avant le 15 déc. 2026|Early bird jusqu''au 15 janv. 2027|En collaboration avec la KU Leuven"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('about.eye', '{"en":"About the meeting","it":"Il congresso","nl":"Over de vergadering","fr":"Le congrès"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('about.n', '{"en":"01","it":"01","nl":"01","fr":"01"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('about.t1', '{"en":"A working meeting,","it":"Un congresso di lavoro,","nl":"Een werkvergadering,","fr":"Un congrès de travail,"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('about.t2', '{"en":"not a showcase.","it":"non una vetrina.","nl":"geen etalage.","fr":"pas une vitrine."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('about.lead', '{"en":"The EEBA Annual Meeting is the dedicated platform for the latest innovations in eye banking, and the place where European eye banks compare practice, not just slides.","it":"Il Congresso Annuale EEBA è la piattaforma dedicata alle ultime innovazioni nell''eye banking, e il luogo in cui le banche degli occhi europee confrontano la pratica, non solo le slide.","nl":"De EEBA Jaarvergadering is hét platform voor de nieuwste innovaties in de oogbankwereld, en de plek waar Europese oogbanken hun praktijk vergelijken, niet alleen hun dia''s.","fr":"Le congrès annuel de l''EEBA est la plateforme dédiée aux dernières innovations en matière de banques d''yeux, et le lieu où les banques européennes confrontent leurs pratiques, pas seulement leurs diapositives."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('about.p1', '{"en":"Over three days, participants engage with a rich scientific programme: symposia, workshops, keynote lectures, free oral and poster presentations, wetlabs and an industry-sponsored session.","it":"In tre giorni i partecipanti affrontano un programma scientifico denso: simposi, workshop, letture magistrali, comunicazioni orali e poster, wetlab e una sessione sponsorizzata dall''industria.","nl":"In drie dagen krijgen deelnemers een rijk wetenschappelijk programma: symposia, workshops, keynotelezingen, vrije voordrachten en posters, wetlabs en een door de industrie gesponsorde sessie.","fr":"En trois jours, les participants suivent un programme scientifique dense : symposiums, ateliers, conférences plénières, communications orales et affichées, wetlabs et une session sponsorisée par l''industrie."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('about.p2', '{"en":"Beyond the scientific content, the meeting offers a rare environment to connect with peers, share expertise and discuss best practices in eye banking and corneal transplantation.","it":"Oltre ai contenuti scientifici, il congresso offre un contesto raro per incontrare i colleghi, condividere competenze e discutere le best practice in eye banking e trapianto corneale.","nl":"Naast de wetenschappelijke inhoud biedt de vergadering een zeldzame omgeving om collega''s te ontmoeten, expertise te delen en best practices in oogbanken en corneatransplantatie te bespreken.","fr":"Au-delà du contenu scientifique, le congrès offre un cadre rare pour rencontrer ses pairs, partager son expertise et discuter des bonnes pratiques en banque d''yeux et en greffe de cornée."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('about.c1t', '{"en":"Scientific programme","it":"Programma scientifico","nl":"Wetenschappelijk programma","fr":"Programme scientifique"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('about.c1d', '{"en":"Symposia, keynotes, free papers and posters across three focused days.","it":"Simposi, letture magistrali, comunicazioni libere e poster in tre giornate.","nl":"Symposia, keynotes, vrije voordrachten en posters over drie dagen.","fr":"Symposiums, plénières, communications libres et posters sur trois journées."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('about.c2t', '{"en":"Hands-on wetlabs","it":"Wetlab pratici","nl":"Praktische wetlabs","fr":"Wetlabs pratiques"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('about.c2d', '{"en":"Limited-capacity practical sessions on preparation, evaluation and tissue handling.","it":"Sessioni pratiche a posti limitati su preparazione, valutazione e gestione del tessuto.","nl":"Praktijksessies met beperkte capaciteit over preparatie, evaluatie en weefselbehandeling.","fr":"Sessions pratiques à places limitées : préparation, évaluation et manipulation des tissus."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('about.c3t', '{"en":"Regulatory clinic","it":"Clinica normativa","nl":"Regelgevingskliniek","fr":"Clinique réglementaire"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('about.c3d', '{"en":"Compliance hurdles, final technical guidelines and ''day one'' readiness under SoHO.","it":"Ostacoli di conformità, linee guida tecniche definitive e prontezza al ''giorno uno'' SoHO.","nl":"Nalevingsdrempels, definitieve technische richtlijnen en ''dag één''-gereedheid onder SoHO.","fr":"Obstacles de conformité, lignes directrices techniques finales et préparation au « jour un » SoHO."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('about.c4t', '{"en":"Peer network","it":"Rete di colleghi","nl":"Collegiaal netwerk","fr":"Réseau de pairs"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('about.c4d', '{"en":"Eye bankers, clinicians, researchers and industry partners from across Europe and beyond.","it":"Eye banker, clinici, ricercatori e partner industriali da tutta Europa e oltre.","nl":"Oogbankmedewerkers, clinici, onderzoekers en industriepartners uit heel Europa en daarbuiten.","fr":"Professionnels des banques d''yeux, cliniciens, chercheurs et partenaires industriels de toute l''Europe et au-delà."}');
