INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('focus.n', '{"en":"02","it":"02","nl":"02","fr":"02"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('focus.t1', '{"en":"From the ","it":"Dal ","nl":"Van het ","fr":"Du "}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('focus.t2', '{"en":"New Scenario","it":"Nuovo Scenario","nl":"Nieuwe Scenario","fr":"Nouveau Scénario"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('focus.t3', '{"en":" to day one readiness.","it":" alla prontezza operativa.","nl":" naar gereedheid op dag één.","fr":" à la préparation opérationnelle."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('focus.lead', '{"en":"EEBA 2026 introduced us to the ''New Scenario'' of the EU SoHO Regulation. EEBA 2027 shifts the focus from theory to immediate application.","it":"EEBA 2026 ci ha introdotti al ''Nuovo Scenario'' del Regolamento europeo SoHO. EEBA 2027 sposta il fuoco dalla teoria all''applicazione immediata.","nl":"EEBA 2026 introduceerde het ''Nieuwe Scenario'' van de Europese SoHO-verordening. EEBA 2027 verschuift de focus van theorie naar directe toepassing.","fr":"EEBA 2026 nous a fait découvrir le « Nouveau Scénario » du règlement européen SoHO. EEBA 2027 déplace l''attention de la théorie vers l''application immédiate."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('focus.p1', '{"en":"Set to take place just four months before the Regulation becomes legally binding in August 2027, this meeting serves as the essential final briefing.","it":"A soli quattro mesi dall''entrata in vigore del Regolamento, ad agosto 2027, questo congresso è il briefing finale indispensabile.","nl":"Deze vergadering vindt plaats slechts vier maanden voordat de verordening in augustus 2027 juridisch bindend wordt, en vormt daarmee de essentiële eindbriefing.","fr":"Se tenant quatre mois seulement avant l''entrée en vigueur du règlement, en août 2027, ce congrès constitue le briefing final indispensable."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('focus.p2', '{"en":"We move beyond general overviews to address specific compliance hurdles, final technical guidelines, and the practical ''day one'' readiness required for every eye bank in Europe.","it":"Andiamo oltre le panoramiche generali per affrontare ostacoli di conformità specifici, le linee guida tecniche definitive e la prontezza operativa richiesta a ogni banca degli occhi europea.","nl":"We gaan verder dan algemene overzichten en behandelen concrete nalevingsdrempels, definitieve technische richtlijnen en de praktische ''dag één''-gereedheid die van elke Europese oogbank wordt verwacht.","fr":"Nous dépassons les panoramas généraux pour traiter des obstacles de conformité précis, des lignes directrices techniques finales et de la préparation concrète attendue de chaque banque d''yeux européenne."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('focus.l1', '{"en":"Specific compliance hurdles, bank by bank","it":"Ostacoli di conformità, banca per banca","nl":"Concrete nalevingsdrempels, bank per bank","fr":"Obstacles de conformité, banque par banque"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('focus.l2', '{"en":"Final technical guidelines and how to read them","it":"Linee guida tecniche definitive e come leggerle","nl":"Definitieve technische richtlijnen en hoe ze te lezen","fr":"Lignes directrices techniques finales et comment les lire"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('focus.l3', '{"en":"Documentation, traceability and vigilance in practice","it":"Documentazione, tracciabilità e vigilanza nella pratica","nl":"Documentatie, traceerbaarheid en waakzaamheid in de praktijk","fr":"Documentation, traçabilité et vigilance en pratique"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('focus.l4', '{"en":"What ''day one'' actually looks like in August 2027","it":"Cosa significa davvero il ''giorno uno'' di agosto 2027","nl":"Hoe ''dag één'' er in augustus 2027 werkelijk uitziet","fr":"À quoi ressemble vraiment le « jour un » d''août 2027"}');
