INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('prog.lead', '{"en":"Provisional structure. The detailed scientific programme is published as sessions are confirmed by the Organising Committee.","it":"Struttura provvisoria. Il programma scientifico dettagliato viene pubblicato man mano che le sessioni sono confermate dal Comitato Organizzatore.","nl":"Voorlopige structuur. Het gedetailleerde wetenschappelijke programma wordt gepubliceerd zodra sessies door het organiserend comité zijn bevestigd.","fr":"Structure provisoire. Le programme scientifique détaillé est publié au fur et à mesure que les sessions sont confirmées par le comité d''organisation."}');
