INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('spk.lead', '{"en":"The Organising Committee is finalising the faculty. Confirmed speakers will be published here as invitations are accepted — the placeholders below show how the section will look.","it":"Il Comitato Organizzatore sta completando la faculty. I relatori confermati saranno pubblicati qui man mano che accettano l''invito — i segnaposto qui sotto mostrano come apparirà la sezione.","nl":"Het organiserend comité stelt de faculty samen. Bevestigde sprekers worden hier gepubliceerd zodra uitnodigingen zijn aanvaard — de plaatshouders hieronder tonen hoe deze sectie eruit zal zien.","fr":"Le comité d''organisation finalise la faculty. Les intervenants confirmés seront publiés ici au fur et à mesure des acceptations — les emplacements ci-dessous montrent l''aspect final de la section."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('spk.r1', '{"en":"Keynote lecture","it":"Lettura magistrale","nl":"Keynotelezing","fr":"Conférence plénière"}');
