INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('spk.r3', '{"en":"Regulatory session","it":"Sessione normativa","nl":"Sessie regelgeving","fr":"Session réglementaire"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('spk.r4', '{"en":"Wetlab faculty","it":"Faculty wetlab","nl":"Wetlab faculty","fr":"Faculty wetlab"}');
