INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('spk.note', '{"en":"Are you interested in contributing to the scientific programme? Submit an abstract or contact the Secretariat.","it":"Vuoi contribuire al programma scientifico? Invia un abstract o contatta la Segreteria.","nl":"Wilt u bijdragen aan het wetenschappelijk programma? Dien een abstract in of neem contact op met het secretariaat.","fr":"Vous souhaitez contribuer au programme scientifique ? Soumettez un résumé ou contactez le secrétariat."}');
