INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('venue.t2', '{"en":"Leuven.","it":"Lovanio.","nl":"Leuven.","fr":"Louvain."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('venue.lead', '{"en":"A 15th-century hall in the heart of a university city — thirty minutes from Brussels Airport and twenty-five from Brussels city centre.","it":"Un''aula del Quattrocento nel cuore di una città universitaria — trenta minuti dall''aeroporto di Bruxelles e venticinque dal centro della capitale.","nl":"Een vijftiende-eeuwse hal in het hart van een universiteitsstad — dertig minuten van Brussels Airport en vijfentwintig van het centrum van Brussel.","fr":"Une halle du XVe siècle au cœur d''une ville universitaire — à trente minutes de l''aéroport de Bruxelles et vingt-cinq du centre de la capitale."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('venue.badge', '{"en":"University Hall · Naamsestraat, Leuven","it":"University Hall · Naamsestraat, Lovanio","nl":"Universiteitshal · Naamsestraat, Leuven","fr":"Halle universitaire · Naamsestraat, Louvain"}');
