INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('venue.v1', '{"en":"University Hall (Universiteitshal), Naamsestraat 22, 3000 Leuven, Belgium","it":"University Hall (Universiteitshal), Naamsestraat 22, 3000 Leuven, Belgio","nl":"Universiteitshal, Naamsestraat 22, 3000 Leuven, België","fr":"Halle universitaire (Universiteitshal), Naamsestraat 22, 3000 Louvain, Belgique"}');
