INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('venue.v2', '{"en":"Thursday 8 – Saturday 10 April 2027","it":"Da giovedì 8 a sabato 10 aprile 2027","nl":"Donderdag 8 tot zaterdag 10 april 2027","fr":"Du jeudi 8 au samedi 10 avril 2027"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('venue.k3', '{"en":"Host","it":"Ospita","nl":"Gastheer","fr":"Hôtes"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('venue.v3', '{"en":"KU Leuven and University Hospital Leuven, in collaboration with EEBA","it":"KU Leuven e Ospedale Universitario di Lovanio, in collaborazione con EEBA","nl":"KU Leuven en UZ Leuven, in samenwerking met EEBA","fr":"KU Leuven et Hôpital universitaire de Louvain, en collaboration avec l''EEBA"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('venue.k4', '{"en":"Airport","it":"Aeroporto","nl":"Luchthaven","fr":"Aéroport"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('venue.v4', '{"en":"Brussels Airport (BRU) — 25 min by direct train to Leuven station","it":"Brussels Airport (BRU) — 25 min di treno diretto per la stazione di Leuven","nl":"Brussels Airport (BRU) — 25 min met de directe trein naar station Leuven","fr":"Brussels Airport (BRU) — 25 min en train direct jusqu''à la gare de Louvain"}');
