INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('venue.v5', '{"en":"12 min on foot, or bus lines through the city centre","it":"12 minuti a piedi, oppure autobus attraverso il centro","nl":"12 minuten te voet, of buslijnen door het centrum","fr":"12 minutes à pied, ou lignes de bus traversant le centre"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('venue.k6', '{"en":"Accommodation","it":"Alloggio","nl":"Overnachting","fr":"Hébergement"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('venue.v6', '{"en":"A list of partner hotels with delegate rates is published with the registration confirmation","it":"L''elenco degli hotel convenzionati con tariffa congressuale è allegato alla conferma di iscrizione","nl":"Een lijst met partnerhotels en deelnemerstarieven wordt bij de inschrijvingsbevestiging meegestuurd","fr":"La liste des hôtels partenaires avec tarifs congressistes est jointe à la confirmation d''inscription"}');
