INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.lead', '{"en":"Fees include access to the full scientific programme, the exhibition, coffee breaks, lunches and the welcome reception. Wetlabs and the gala dinner are optional add-ons with limited capacity.","it":"La quota comprende l''accesso all''intero programma scientifico, all''area espositiva, coffee break, pranzi e cocktail di benvenuto. Wetlab e cena di gala sono opzioni a posti limitati.","nl":"De deelnamekosten omvatten toegang tot het volledige wetenschappelijke programma, de expositie, koffiepauzes, lunches en de welkomstreceptie. Wetlabs en het galadiner zijn optioneel met beperkte capaciteit.","fr":"Les frais comprennent l''accès à l''ensemble du programme scientifique, à l''exposition, les pauses café, les déjeuners et le cocktail de bienvenue. Wetlabs et dîner de gala sont des options à places limitées."}');
