INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.roles.r5', '{"en":"Quality / Regulatory","it":"Qualità / Regolatorio","nl":"Kwaliteit / Regelgeving","fr":"Qualité / Réglementaire"}');
