INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.consent1', '{"en":"I accept the terms of participation and the cancellation policy.","it":"Accetto le condizioni di partecipazione e la politica di cancellazione.","nl":"Ik aanvaard de deelnamevoorwaarden en het annuleringsbeleid.","fr":"J''accepte les conditions de participation et la politique d''annulation."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.consent2', '{"en":"I agree to the processing of my data for the organisation of the meeting (GDPR).","it":"Acconsento al trattamento dei miei dati per l''organizzazione del congresso (GDPR).","nl":"Ik ga akkoord met de verwerking van mijn gegevens voor de organisatie van de vergadering (AVG).","fr":"J''accepte le traitement de mes données pour l''organisation du congrès (RGPD)."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.consent3', '{"en":"I would like to receive news about EEBA meetings and webinars.","it":"Desidero ricevere notizie sui congressi e i webinar EEBA.","nl":"Ik ontvang graag nieuws over EEBA-vergaderingen en webinars.","fr":"Je souhaite recevoir des nouvelles des congrès et webinaires EEBA."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.payTitle', '{"en":"Payment","it":"Pagamento","nl":"Betaling","fr":"Paiement"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.payLead', '{"en":"This prototype does not process real payments. In production this step connects to the payment provider (card, SEPA transfer or institutional invoice).","it":"Questo prototipo non elabora pagamenti reali. In produzione questo passaggio si collega al provider di pagamento (carta, bonifico SEPA o fattura istituzionale).","nl":"Dit prototype verwerkt geen echte betalingen. In productie maakt deze stap verbinding met de betaalprovider (kaart, SEPA-overschrijving of institutionele factuur).","fr":"Ce prototype ne traite aucun paiement réel. En production, cette étape se connecte au prestataire de paiement (carte, virement SEPA ou facture institutionnelle)."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.pay.redirect', '{"en":"You''ll be taken to a secure payment page.","it":"Verrai portato su una pagina di pagamento sicura.","nl":"U wordt naar een beveiligde betaalpagina gebracht.","fr":"Vous serez dirigé vers une page de paiement sécurisée."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.pay.offlineNote', '{"en":"Your registration is recorded straight away and confirmed once payment arrives.","it":"L''iscrizione viene registrata subito e confermata quando il pagamento arriva.","nl":"Uw inschrijving wordt meteen vastgelegd en bevestigd zodra de betaling binnen is.","fr":"L''inscription est enregistrée immédiatement et confirmée dès réception du paiement."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.pay.preview', '{"en":"Preview mode — no real payment is taken.","it":"Modalità anteprima — nessun pagamento reale viene addebitato.","nl":"Voorbeeldmodus — er wordt niets echt afgeschreven.","fr":"Mode aperçu — aucun paiement réel n''est prélevé."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.pay.processing', '{"en":"Completing your payment…","it":"Sto completando il pagamento…","nl":"Bezig met afronden van de betaling…","fr":"Finalisation du paiement…"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.pay.okT', '{"en":"Payment received.","it":"Pagamento ricevuto.","nl":"Betaling ontvangen.","fr":"Paiement reçu."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.pay.okP', '{"en":"Your place is confirmed. The confirmation and invoice are on their way to your inbox.","it":"Il tuo posto è confermato. Conferma e fattura stanno arrivando nella tua casella.","nl":"Uw plaats is bevestigd. Bevestiging en factuur zijn onderweg naar uw mailbox.","fr":"Votre place est confirmée. La confirmation et la facture arrivent dans votre boîte mail."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.pay.failT', '{"en":"Payment not completed.","it":"Pagamento non completato.","nl":"Betaling niet afgerond.","fr":"Paiement non abouti."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.pay.failP', '{"en":"Nothing has been charged. Your registration is saved — you can try again or choose another method.","it":"Non è stato addebitato nulla. L''iscrizione è salvata: puoi riprovare o scegliere un altro metodo.","nl":"Er is niets afgeschreven. Uw inschrijving is bewaard: probeer opnieuw of kies een andere methode.","fr":"Rien n''a été prélevé. Votre inscription est enregistrée : réessayez ou choisissez un autre moyen."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.pay.retry', '{"en":"Try again","it":"Riprova","nl":"Opnieuw proberen","fr":"Réessayer"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.pay.pending', '{"en":"Awaiting payment","it":"In attesa di pagamento","nl":"Wacht op betaling","fr":"En attente de paiement"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.pm.card', '{"en":"Credit / debit card","it":"Carta di credito / debito","nl":"Krediet- / debetkaart","fr":"Carte bancaire"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.pm.sepa', '{"en":"SEPA bank transfer","it":"Bonifico SEPA","nl":"SEPA-overschrijving","fr":"Virement SEPA"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.pm.inv', '{"en":"Institutional invoice","it":"Fattura istituzionale","nl":"Institutionele factuur","fr":"Facture institutionnelle"}');
