INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.sumTitle', '{"en":"Your registration","it":"La tua iscrizione","nl":"Uw inschrijving","fr":"Votre inscription"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.sumSub', '{"en":"Prices in EUR, VAT included","it":"Prezzi in EUR, IVA inclusa","nl":"Prijzen in EUR, incl. btw","fr":"Prix en EUR, TVA comprise"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.sumEmpty', '{"en":"Select a category to see the total","it":"Seleziona una categoria per vedere il totale","nl":"Kies een categorie om het totaal te zien","fr":"Choisissez une catégorie pour voir le total"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.sumTier', '{"en":"Delegate fee","it":"Quota delegato","nl":"Deelnamekosten","fr":"Frais d''inscription"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.sumAdd', '{"en":"Add-ons","it":"Opzioni","nl":"Aanvullingen","fr":"Options"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.sumTot', '{"en":"Total","it":"Totale","nl":"Totaal","fr":"Total"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.sumNote', '{"en":"You will receive a confirmation email with your invoice and a QR badge within a few minutes.","it":"Riceverai entro pochi minuti un''email di conferma con la fattura e il badge QR.","nl":"U ontvangt binnen enkele minuten een bevestigingsmail met uw factuur en een QR-badge.","fr":"Vous recevrez sous quelques minutes un e-mail de confirmation avec votre facture et un badge QR."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.confirmT', '{"en":"You''re registered.","it":"Iscrizione completata.","nl":"U bent ingeschreven.","fr":"Vous êtes inscrit."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.confirmP', '{"en":"We''ve sent the confirmation and invoice to your email address. Your badge QR code is attached — bring it to the registration desk in Leuven.","it":"Abbiamo inviato conferma e fattura al tuo indirizzo email. Il QR del badge è in allegato — portalo al desk registrazioni a Lovanio.","nl":"We hebben de bevestiging en factuur naar uw e-mailadres gestuurd. Uw badge-QR-code zit erbij — neem die mee naar de registratiebalie in Leuven.","fr":"Nous avons envoyé la confirmation et la facture à votre adresse e-mail. Le QR de votre badge est en pièce jointe — présentez-le au bureau d''accueil à Louvain."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.confirmRef', '{"en":"Booking reference","it":"Codice prenotazione","nl":"Boekingsreferentie","fr":"Référence de réservation"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.errReq', '{"en":"This field is required","it":"Campo obbligatorio","nl":"Dit veld is verplicht","fr":"Ce champ est obligatoire"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.errEmail', '{"en":"Enter a valid email address","it":"Inserisci un indirizzo email valido","nl":"Voer een geldig e-mailadres in","fr":"Saisissez une adresse e-mail valide"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.errMatch', '{"en":"The two email addresses don''t match","it":"I due indirizzi email non coincidono","nl":"De twee e-mailadressen komen niet overeen","fr":"Les deux adresses e-mail ne correspondent pas"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.errTier', '{"en":"Please choose a delegate category","it":"Scegli una categoria delegato","nl":"Kies een deelnemerscategorie","fr":"Choisissez une catégorie"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.errConsent', '{"en":"Please accept the required terms","it":"Accetta le condizioni obbligatorie","nl":"Aanvaard de verplichte voorwaarden","fr":"Veuillez accepter les conditions obligatoires"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('reg.toastAdded', '{"en":"Added to your registration","it":"Aggiunto alla tua iscrizione","nl":"Toegevoegd aan uw inschrijving","fr":"Ajouté à votre inscription"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('abs.eye', '{"en":"Call for abstracts","it":"Call for abstract","nl":"Oproep voor abstracts","fr":"Appel à résumés"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('abs.n', '{"en":"07","it":"07","nl":"07","fr":"07"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('abs.t1', '{"en":"Share what","it":"Condividi","nl":"Deel wat","fr":"Partagez ce"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('abs.t2', '{"en":"you''ve learned.","it":"quello che hai imparato.","nl":"u geleerd heeft.","fr":"que vous avez appris."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('abs.lead', '{"en":"Free oral and poster presentations are the backbone of the meeting. Abstracts are peer-reviewed by the Scientific Committee and the best contributions receive an award at the closing session.","it":"Le comunicazioni orali e i poster sono la spina dorsale del congresso. Gli abstract sono valutati dal Comitato Scientifico e i contributi migliori ricevono un premio nella sessione di chiusura.","nl":"Vrije voordrachten en posters vormen de ruggengraat van de vergadering. Abstracts worden beoordeeld door het wetenschappelijk comité en de beste bijdragen krijgen een prijs tijdens de slotsessie.","fr":"Les communications orales et affichées sont la colonne vertébrale du congrès. Les résumés sont évalués par le comité scientifique et les meilleures contributions reçoivent un prix lors de la session de clôture."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('abs.d1', '{"en":"Abstract submission opens","it":"Apertura invio abstract","nl":"Indiening opent","fr":"Ouverture des soumissions"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('abs.d1v', '{"en":"1 September 2026","it":"1 settembre 2026","nl":"1 september 2026","fr":"1er septembre 2026"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('abs.d2', '{"en":"Submission deadline","it":"Scadenza invio","nl":"Uiterste indieningsdatum","fr":"Date limite de soumission"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('abs.d2v', '{"en":"15 December 2026","it":"15 dicembre 2026","nl":"15 december 2026","fr":"15 décembre 2026"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('abs.d3', '{"en":"Notification to authors","it":"Comunicazione agli autori","nl":"Bericht aan auteurs","fr":"Notification aux auteurs"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('abs.d3v', '{"en":"31 January 2027","it":"31 gennaio 2027","nl":"31 januari 2027","fr":"31 janvier 2027"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('abs.d4', '{"en":"Presenter registration deadline","it":"Iscrizione del presentatore","nl":"Inschrijving presenterende auteur","fr":"Inscription de l''auteur présentateur"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('abs.d4v', '{"en":"28 February 2027","it":"28 febbraio 2027","nl":"28 februari 2027","fr":"28 février 2027"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('abs.note', '{"en":"Maximum 300 words, structured abstract, English only. Presenting authors must be registered delegates.","it":"Massimo 300 parole, abstract strutturato, solo in inglese. Gli autori presentatori devono essere delegati iscritti.","nl":"Maximaal 300 woorden, gestructureerd abstract, uitsluitend in het Engels. Presenterende auteurs moeten ingeschreven deelnemers zijn.","fr":"300 mots maximum, résumé structuré, en anglais uniquement. Les auteurs présentateurs doivent être inscrits au congrès."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('faq.eye', '{"en":"Practical questions","it":"Domande pratiche","nl":"Praktische vragen","fr":"Questions pratiques"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('faq.n', '{"en":"09","it":"09","nl":"09","fr":"09"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('faq.t1', '{"en":"Frequently","it":"Domande","nl":"Veelgestelde","fr":"Questions"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('faq.t2', '{"en":"asked.","it":"frequenti.","nl":"vragen.","fr":"fréquentes."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('faq.q1', '{"en":"What is included in the registration fee?","it":"Cosa comprende la quota di iscrizione?","nl":"Wat is inbegrepen bij de deelnamekosten?","fr":"Que comprennent les frais d''inscription ?"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('faq.a1', '{"en":"Access to the full scientific programme and exhibition, delegate pack, coffee breaks, lunches on all programme days and the welcome reception on Thursday evening. Wetlabs, the gala dinner and accompanying-person access are optional add-ons.","it":"Accesso all''intero programma scientifico e all''area espositiva, kit congressuale, coffee break, pranzi in tutte le giornate di programma e cocktail di benvenuto del giovedì sera. Wetlab, cena di gala e accesso accompagnatori sono opzioni a pagamento.","nl":"Toegang tot het volledige wetenschappelijke programma en de expositie, deelnemerspakket, koffiepauzes, lunches op alle programmadagen en de welkomstreceptie op donderdagavond. Wetlabs, het galadiner en toegang voor begeleiders zijn optioneel.","fr":"L''accès à l''ensemble du programme scientifique et à l''exposition, la pochette congressiste, les pauses café, les déjeuners de toutes les journées et le cocktail de bienvenue du jeudi soir. Wetlabs, dîner de gala et accès accompagnant sont en option."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('faq.q2', '{"en":"Can I register on site?","it":"Posso iscrivermi in sede?","nl":"Kan ik mij ter plaatse inschrijven?","fr":"Puis-je m''inscrire sur place ?"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('faq.a2', '{"en":"Yes, subject to availability, at the on-site rate. Wetlabs and the gala dinner almost always sell out in advance, so we strongly recommend booking those online.","it":"Sì, salvo disponibilità, alla tariffa on-site. Wetlab e cena di gala si esauriscono quasi sempre in anticipo, quindi consigliamo caldamente di prenotarli online.","nl":"Ja, afhankelijk van beschikbaarheid, tegen het on-site tarief. Wetlabs en het galadiner zijn vrijwel altijd vooraf uitverkocht, dus we raden sterk aan die online te boeken.","fr":"Oui, sous réserve de disponibilité, au tarif sur place. Les wetlabs et le dîner de gala affichent presque toujours complet à l''avance : nous recommandons vivement de les réserver en ligne."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('faq.q3', '{"en":"What is the cancellation policy?","it":"Qual è la politica di cancellazione?","nl":"Wat is het annuleringsbeleid?","fr":"Quelle est la politique d''annulation ?"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('faq.a3', '{"en":"Full refund minus a handling fee until 15 February 2027, 50% until 15 March 2027, no refund afterwards. Registrations are transferable to another delegate from the same institution at any time, free of charge.","it":"Rimborso totale meno le spese di gestione fino al 15 febbraio 2027, 50% fino al 15 marzo 2027, nessun rimborso successivamente. L''iscrizione è sempre trasferibile a un altro delegato dello stesso ente, gratuitamente.","nl":"Volledige terugbetaling minus administratiekosten tot 15 februari 2027, 50% tot 15 maart 2027, daarna geen terugbetaling. Inschrijvingen zijn altijd kosteloos overdraagbaar aan een andere deelnemer van dezelfde instelling.","fr":"Remboursement intégral moins les frais de dossier jusqu''au 15 février 2027, 50 % jusqu''au 15 mars 2027, aucun remboursement ensuite. L''inscription est transférable gratuitement et à tout moment à un autre congressiste du même établissement."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('faq.q4', '{"en":"Do I need a visa or an invitation letter?","it":"Serve un visto o una lettera d''invito?","nl":"Heb ik een visum of uitnodigingsbrief nodig?","fr":"Ai-je besoin d''un visa ou d''une lettre d''invitation ?"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('faq.a4', '{"en":"Belgium is in the Schengen Area. If you need a visa, the Secretariat can issue a personal letter of invitation after your registration has been paid. Please allow at least eight weeks.","it":"Il Belgio è nell''area Schengen. Se ti serve un visto, la Segreteria può emettere una lettera d''invito personale dopo il pagamento dell''iscrizione. Prevedi almeno otto settimane.","nl":"België ligt in de Schengenzone. Als u een visum nodig heeft, kan het secretariaat na betaling van uw inschrijving een persoonlijke uitnodigingsbrief opstellen. Houd rekening met minstens acht weken.","fr":"La Belgique fait partie de l''espace Schengen. Si un visa est nécessaire, le secrétariat peut délivrer une lettre d''invitation personnelle après paiement de l''inscription. Comptez au moins huit semaines."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('faq.q5', '{"en":"Will sessions be recorded?","it":"Le sessioni saranno registrate?","nl":"Worden de sessies opgenomen?","fr":"Les sessions seront-elles enregistrées ?"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('faq.a5', '{"en":"Selected sessions are recorded and made available to registered delegates on EEBA Campus after the meeting. Wetlabs and the General Assembly are not recorded.","it":"Alcune sessioni sono registrate e rese disponibili ai delegati iscritti su EEBA Campus dopo il congresso. Wetlab e Assemblea Generale non sono registrati.","nl":"Geselecteerde sessies worden opgenomen en na afloop beschikbaar gesteld aan ingeschreven deelnemers op EEBA Campus. Wetlabs en de Algemene Vergadering worden niet opgenomen.","fr":"Certaines sessions sont enregistrées et mises à disposition des congressistes inscrits sur EEBA Campus après le congrès. Les wetlabs et l''Assemblée générale ne sont pas enregistrés."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('faq.q6', '{"en":"Can I get an institutional invoice?","it":"Posso avere una fattura istituzionale?","nl":"Kan ik een institutionele factuur krijgen?","fr":"Puis-je obtenir une facture institutionnelle ?"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('faq.a6', '{"en":"Yes. Choose ''Institutional invoice'' at the payment step and enter your VAT or tax number. The invoice is issued by the EEBA Secretariat in Venice and payment is due within 30 days.","it":"Sì. Scegli ''Fattura istituzionale'' al passaggio del pagamento e inserisci la partita IVA. La fattura è emessa dalla Segreteria EEBA di Venezia con pagamento a 30 giorni.","nl":"Ja. Kies ''Institutionele factuur'' bij de betaalstap en vul uw btw-nummer in. De factuur wordt uitgegeven door het EEBA-secretariaat in Venetië, betaalbaar binnen 30 dagen.","fr":"Oui. Choisissez « Facture institutionnelle » à l''étape du paiement et indiquez votre numéro de TVA. La facture est émise par le secrétariat de l''EEBA à Venise, payable sous 30 jours."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('faq.q7', '{"en":"Is the venue accessible?","it":"La sede è accessibile?","nl":"Is de locatie toegankelijk?","fr":"Le lieu est-il accessible ?"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('faq.a7', '{"en":"University Hall is wheelchair accessible with a dedicated entrance and lift. Please note any accessibility requirements in the registration form so we can arrange support.","it":"University Hall è accessibile in sedia a rotelle, con ingresso dedicato e ascensore. Segnala eventuali esigenze di accessibilità nel modulo di iscrizione così possiamo organizzare il supporto.","nl":"De Universiteitshal is rolstoeltoegankelijk met een aparte ingang en lift. Vermeld eventuele toegankelijkheidswensen in het inschrijvingsformulier zodat wij ondersteuning kunnen regelen.","fr":"La Halle universitaire est accessible en fauteuil roulant, avec une entrée dédiée et un ascenseur. Signalez vos besoins d''accessibilité dans le formulaire d''inscription afin que nous puissions organiser l''assistance."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('spon.eye', '{"en":"Partners","it":"Partner","nl":"Partners","fr":"Partenaires"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('spon.n', '{"en":"08","it":"08","nl":"08","fr":"08"}');
