INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('spon.t2', '{"en":"partners.","it":"industriali.","nl":"partners.","fr":"industriels."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('spon.lead', '{"en":"The meeting is supported by the companies that build the tools eye banks work with every day. Sponsorship packages for EEBA 2027 are available from the Secretariat.","it":"Il congresso è sostenuto dalle aziende che costruiscono gli strumenti con cui le banche degli occhi lavorano ogni giorno. I pacchetti di sponsorizzazione EEBA 2027 sono disponibili presso la Segreteria.","nl":"De vergadering wordt ondersteund door de bedrijven die de instrumenten bouwen waarmee oogbanken dagelijks werken. Sponsorpakketten voor EEBA 2027 zijn verkrijgbaar bij het secretariaat.","fr":"Le congrès est soutenu par les entreprises qui fabriquent les outils utilisés chaque jour par les banques d''yeux. Les formules de partenariat EEBA 2027 sont disponibles auprès du secrétariat."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('spon.cta', '{"en":"Become a partner","it":"Diventa partner","nl":"Word partner","fr":"Devenir partenaire"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('band.t', '{"en":"Leuven, 8–10 April 2027.","it":"Lovanio, 8–10 aprile 2027.","nl":"Leuven, 8–10 april 2027.","fr":"Louvain, 8–10 avril 2027."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('band.p', '{"en":"Registration is open and early-bird rates run until 15 January 2027. Wetlab and gala dinner places are limited.","it":"Le iscrizioni sono aperte e la tariffa early bird è valida fino al 15 gennaio 2027. I posti per wetlab e cena di gala sono limitati.","nl":"De inschrijving is open en de early-birdtarieven gelden tot 15 januari 2027. Plaatsen voor wetlab en galadiner zijn beperkt.","fr":"Les inscriptions sont ouvertes et le tarif early bird court jusqu''au 15 janvier 2027. Les places en wetlab et au dîner de gala sont limitées."}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('band.cta', '{"en":"Register now","it":"Iscriviti ora","nl":"Nu inschrijven","fr":"S''inscrire"}');
INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('foot.about', '{"en":"The XXXVIII Annual Meeting of the European Eye Bank Association, organised in collaboration with KU Leuven and University Hospital Leuven.","it":"Il XXXVIII Congresso Annuale della European Eye Bank Association, organizzato in collaborazione con KU Leuven e l''Ospedale Universitario di Lovanio.","nl":"De XXXVIIIe Jaarvergadering van de European Eye Bank Association, georganiseerd in samenwerking met KU Leuven en UZ Leuven.","fr":"Le XXXVIIIe Congrès annuel de l''European Eye Bank Association, organisé en collaboration avec la KU Leuven et l''Hôpital universitaire de Louvain."}');
