INSERT OR IGNORE INTO translations (tkey, value_json) VALUES ('foot.disc', '{"en":"Demo prototype. Programme, fees and deadlines are indicative and not an official EEBA publication.","it":"Prototipo dimostrativo. Programma, quote e scadenze sono indicativi e non costituiscono una pubblicazione ufficiale EEBA.","nl":"Demonstratieprototype. Programma, tarieven en deadlines zijn indicatief en vormen geen officiële EEBA-publicatie.","fr":"Prototype de démonstration. Programme, tarifs et échéances sont indicatifs et ne constituent pas une publication officielle de l''EEBA."}');

